from collections import Counter

def min_window(s: str, t: str) -> str:
    if not s or not t:
        return ""

    need = Counter(t)
    required = len(need)

    best_left = best_right = float('inf')
    best_len = float('inf')

    have = {}
    have_count = 0
    left = 0

    for right, ch in enumerate(s):
        if ch in need:
            have[ch] = have.get(ch, 0) + 1
            if have[ch] == need[ch]:
                have_count += 1

        while have_count == required:
            # try to shrink from left
            if right - left + 1 < best_len:
                best_len = right - left + 1
                best_left = left
                best_right = right

            ch_left = s[left]
            if ch_left in need:
                if have[ch_left] == need[ch_left]:
                    have_count -= 1
                have[ch_left] -= 1
            left += 1

    if best_len == float('inf'):
        return ""
    return s[best_left:best_right + 1]
