def calculate(expression: str) -> int:
    def compute(operands, operators):
        while operators:
            op = operators.pop()
            right = operands.pop()
            left = operands.pop()
            if op == '+':
                operands.append(left + right)
            elif op == '-':
                operands.append(left - right)
            elif op == '*':
                operands.append(left * right)
            elif op == '/':
                operands.append(int(left / right))

    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    tokens = []
    i = 0
    n = len(expression)
    while i < n:
        if expression[i] == ' ':
            i += 1
            continue
        if expression[i] in '()+-*/':
            tokens.append(expression[i])
            i += 1
        else:
            num = ''
            while i < n and expression[i].isdigit():
                num += expression[i]
                i += 1
            tokens.append(num)

    operands = []
    operators = []
    i = 0
    while i < len(tokens):
        token = tokens[i]
        if token == '(':
            operators.append(token)
        elif token == ')':
            while operators[-1] != '(':
                compute(operands, operators)
            operators.pop()  # Remove '('
        elif token in '+-*/':
            while (operators and operators[-1] != '(' and
                   precedence(operators[-1]) >= precedence(token)):
                compute(operands, operators)
            operators.append(token)
        else:  # Number
            operands.append(int(token))
        i += 1

    while operators:
        compute(operands, operators)

    return operands[0] if operands else 0
